INSERT INTO faqs (program_id, question, answer, sort_order) VALUES
(NULL, 'Apakah sertifikat pelatihan online sama sah dengan offline?', 'Ya. Sertifikat resmi dari pelatihan online maupun offline memiliki kekuatan hukum yang sama dan diakui secara nasional di seluruh Indonesia.', 1),
(NULL, 'Berapa lama sertifikat terbit setelah pelatihan?', 'Setelah ujian kompetensi selesai, sertifikat umumnya diterbitkan dalam beberapa minggu. Tim kami membantu proses administrasinya hingga sertifikat terbit.', 2),
(NULL, 'Apakah harga sudah termasuk ujian dan sertifikat?', 'Ya, biaya yang tertera sudah termasuk pelatihan, modul, ujian kompetensi, dan penerbitan sertifikat resmi. Tanpa biaya tersembunyi.', 3),
(NULL, 'Apakah bisa mengikuti pelatihan dari luar kota?', 'Bisa. Banyak program tersedia secara online via Zoom sehingga dapat diikuti dari seluruh Indonesia, dengan sertifikat yang tetap sah.', 4),
(NULL, 'Apakah tersedia pendaftaran untuk grup atau perusahaan?', 'Tersedia. Untuk pendaftaran grup atau in-house perusahaan, hubungi tim kami via WhatsApp untuk penawaran jadwal dan biaya khusus.', 5),
(NULL, 'Bagaimana cara mendaftar?', 'Cukup klik tombol WhatsApp di halaman ini. Tim kami akan membantu memilih program, menjelaskan jadwal batch terdekat, dan proses pendaftaran hingga selesai.', 6);
